    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    x, y = 0, 0
    current_step = 0
    target_steps = {}

    def within_bounds(x, y):
        return 0 <= x < h and 0 <= y < w

    def get_next_position(direction, distance):
        dx, dy = directions[direction]
        nx, ny = x + dx * distance, y + dy * distance
        while within_bounds(nx, ny) and pattern[nx][ny] == '.':
            nx += dx
            ny += dy
        return max(0, min(h - 1, nx)), max(0, min(w - 1, ny))

    for i in range(n):
        direction, distance = commands[i].split()
        distance = int(distance)
        nx, ny = get_next_position(direction, distance)
        while (nx, ny) != (x, y):
            if pattern[x][y] == '#':
                target_steps[(x, y)] = current_step
            x, y = nx, ny
            current_step += 1
            nx, ny = get_next_position(direction, distance)
        if pattern[x][y] == '#':
            target_steps[(x, y)] = current_step

    if not target_steps:
        return -1, -1

    min_time = float('inf')
    max_time = 0

    for (tx, ty), step in target_steps.items():
        min_time = min(min_time, step)
        max_time = max(max_time, step)

    return min_time, max_time

