def turtle_drawing(h: int, w: int, n: int, pattern: list, commands: list) -> Tuple[int, int]:
    # Initialize the board and marker position
    board = [['.' for _ in range(w)] for _ in range(h)]
    x, y = h - 1, 0  # Starting position at bottom-left corner

    # Function to check if a move is within bounds
    def in_bounds(x, y):
        return 0 <= x < h and 0 <= y < w

    # Apply commands to the board
    for i in range(n):
        direction, dist = commands[i].split()
        dist = int(dist)

        for j in range(dist):
            dx, dy = 0, 0
            if direction == 'up':
                dx = -1
            elif direction == 'down':
                dx = 1
            elif direction == 'left':
                dy = -1
            elif direction == 'right':
                dy = 1

            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny):
                if pattern[nx][ny] == '#':
                    board[nx][ny] = str(i + 1)
                else:
                    board[nx][ny] = '.'
                x, y = nx, ny

    # Find the minimum and maximum steps
    min_steps = float('inf')
    max_steps = 0
    found_target = False
    for i in range(h):
        for j in range(w):
            if board[i][j].isdigit():
                steps = int(board[i][j])
                if steps < min_steps:
                    min_steps = steps
                if steps > max_steps:
                    max_steps = steps
                if steps == n:
                    found_target = True

    if not found_target:
        return -1, -1

    return min_steps, max_steps

