        x, y = 0, 0
        steps = [(0, -1), (0, 1), (-1, 0), (1, 0)]
        for i, (dx, dy) in enumerate(steps):
            if commands[i].split()[0] == 'up':
                dx, dy = -dy, dx
            elif commands[i].split()[0] == 'down':
                dx, dy = dy, dx
            dist = int(commands[i].split()[1])
            if end_time >= dist * (i + 1):
                x += dx * dist
                y += dy * dist
                if not (0 <= x < w and 0 <= y < h):
                    return False
                if pattern[y][x] != '.':
                    return False
        return True

    min_time = 0
    max_time = sum(int(cmd.split()[1]) for cmd in commands)

    while min_time < max_time:
        mid_time = (min_time + max_time) // 2
        if can_draw(mid_time):
            max_time = mid_time
        else:
            min_time = mid_time + 1

    return (max_time, max_time) if can_draw(max_time) else (-1, -1)

