def min_max_drying_time(h, w, n, board, commands):
    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    min_time = float('inf')
    max_time = 0

    def in_bounds(x, y):
        return 0 <= x < h and 0 <= y < w

    def draw_path(commands):
        x, y = h-1, 0
        time = 0
        visited = [[False] * w for _ in range(h)]

        for command in commands:
            dir, dist = command.split()
            dx, dy = directions[dir]
            for _ in range(int(dist)):
                nx, ny = x + dx, y + dy
                if in_bounds(nx, ny):
                    time += 1
                    if board[nx][ny] == '#' and not visited[nx][ny]:
                        visited[nx][ny] = True
                    x, y = nx, ny
                else:
                    break

        return time, any(not v for row in visited for v in row)

    def backtracking(time, x, y, visited):
        nonlocal min_time, max_time
        if time > max_time:
            max_time = time
        if time >= min_time:
            return

        if all(all(v for v in row) for row in visited):
            min_time = min(min_time, time)
            return

        for dir, (dx, dy) in directions.items():
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny) and not visited[nx][ny]:
                visited[nx][ny] = True
                backtracking(time + int(dirs[(nx, ny)] != dir), nx, ny, visited)
                visited[nx][ny] = False

    initial_time, possible = draw_path(commands)
    if not possible:
        return -1, -1

    visited = [[False] * w for _ in range(h)]
    visited[h-1][0] = True
    backtracking(initial_time, h-1, 0, visited)

    return min_time, max_time

