                        return -1, -1
                else:
                    x, y = nx, ny
        return x, y, t

    start_x, start_y = 0, 0
    min_t, max_t = float('inf'), float('-inf')

    def find_bounds(start_x, start_y):
        nonlocal min_t, max_t
        x, y, t = simulate(commands, start_x, start_y)
        if x == start_x and y == start_y and t >= 0:
