        return steps, x, y

    total_steps, x, y = simulate(commands)
    if (x, y) != (h-1, w-1) or len(visited) != sum(pattern[i].count('#') for i in range(h)):
        return -1, -1

    def check_dry_out(end_time):
        x, y = 0, 0
        visited = set()
        steps = 0
        for direction, distance in commands[:end_time]:
            dx, dy = 0, 0
            if direction == 'up':
                dy = -1
            elif direction == 'down':
                dy = 1
            elif direction == 'left':
                dx = -1
            elif direction == 'right':
                dx = 1
            for _ in range(distance):
                nx, ny = x + dx, y + dy
                if not is_within_bounds(nx, ny):
                    break
                if (nx, ny) in visited:
                    break
                x, y = nx, ny
                visited.add((x, y))
                steps += 1
                if steps > end_time:
                    return False
        return True

    min_steps = 0
    max_steps = total_steps
    while min_steps < max_steps:
        mid_steps = (min_steps + max_steps) // 2
        if check_dry_out(mid_steps):
            max_steps = mid_steps
        else:
            min_steps = mid_steps + 1
    if not check_dry_out(max_steps):
        max_steps = -1

    return max_steps, total_steps

